export type AccountWallet = {
  id: string;
  family: WalletFamily;
  address: string;
  kind?: "external" | "embedded" | "smart_account";
  provider?: string;
  providerWalletId?: string;
  chainScope?: string;
  chainId?: number;
  linkedVia:
    | "siwe"
    | "siws"
    | "para"
    | "privy"
    | "challenge"
    | "import"
    | "observed"
    | "migration"
    | (string & {});
  label?: string;
  verifiedAt?: number;
  lastSeenAt?: number;
  capability?: "read" | "write";
};

export type LinkWalletInput = {
  accountId?: string;
  family: WalletFamily;
  address: string;
  chainId?: number;
};

export type UpdateWalletInput = {
  walletId: string;
  label?: string | null;
};

export type UpdateLinkedAccountInput = {
  identityId: string;
  displayLabel?: string | null;
};

export type UpdateAccountInput = {
  displayName?: string | null;
  avatarUrl?: string | null;
};

export type AccountRuntime = {
  status: AccountRuntimeStatus;
  user?: AomiUserRef;
  linkedAccounts: LinkedAuthAccount[];
  wallets: AccountWallet[];
  refresh: () => Promise<void>;
  signOut?: () => Promise<void>;
  deleteAccount?: () => Promise<void>;
  updateAccount?: (input: UpdateAccountInput) => Promise<void>;
  linkWallet?: (input: LinkWalletInput) => Promise<void>;
  updateAuthIdentity?: (input: UpdateLinkedAccountInput) => Promise<void>;
  updateWallet?: (input: UpdateWalletInput) => Promise<void>;
  unlinkWallet?: (walletId: string) => Promise<void>;
  unlinkAuthIdentity?: (identityId: string) => Promise<void>;
};

"use client";

import type { AccountRuntime } from "./types";

export const DISABLED_ACCOUNT_RUNTIME: AccountRuntime = {
  status: "disabled",
  linkedAccounts: [],
  wallets: [],
  refresh: async () => undefined,
};

import type { AomiAccountCredential } from "../types";
import type { AccountRuntime, AccountWallet } from "./types";

export type AomiBackendAccountResponse = {
  user: AccountRuntime["user"] | null;
  linkedAccounts: AccountRuntime["linkedAccounts"];
  wallets: AccountWallet[];
  session: { betterAuthUserId: string; expiresAt?: number } | null;
};

export type AomiBackendProviderExchangeResponse = {
  status: "linked" | "noop";
  account?: AomiBackendAccountResponse;
};

export type AomiBackendLinkWalletResponse = {
  status: "linked" | "noop";
  account?: AomiBackendAccountResponse;
};

export type AomiBackendDeleteAccountResponse = {
  status: "deactivated";
  revokedIdentities: number;
  revokedWallets: number;
};

export type AomiBackendNonceResponse = {
  nonce: string;
  domain?: string;
  uri?: string;
};

export type AomiBackendAccountEndpointConfig = Partial<{
  accountPath: string;
  signOutPath: string;
  existingSessionProviderExchangePath: string;
  newSessionProviderExchangePath: string;
  walletLinkPath: string;
  walletPath: (walletId: string) => string;
  identityPath: (identityId: string) => string;
  siweNoncePath: string;
  siweVerifyPath: string;
}>;

const DEFAULT_ENDPOINTS = {
  accountPath: "/api/aomi/account",
  signOutPath: "/api/aomi/sign-out",
  existingSessionProviderExchangePath: "/api/aomi/provider/exchange",
  newSessionProviderExchangePath: "/api/auth/aomi/provider/exchange",
  walletLinkPath: "/api/aomi/wallets/link",
  walletPath: (walletId: string) =>
    `/api/aomi/wallets/${encodeURIComponent(walletId)}`,
  identityPath: (identityId: string) =>
    `/api/aomi/identities/${encodeURIComponent(identityId)}`,
  siweNoncePath: "/api/auth/siwe/nonce",
  siweVerifyPath: "/api/auth/siwe/verify",
} satisfies Required<AomiBackendAccountEndpointConfig>;

export function createAomiBackendAccountClient(input: {
  baseUrl?: string;
  endpoints?: AomiBackendAccountEndpointConfig;
  fetch?: typeof fetch;
}) {
  const baseUrl = normalizeBaseUrl(input.baseUrl);
  const fetchImpl = input.fetch ?? fetch;
  const endpoints = { ...DEFAULT_ENDPOINTS, ...(input.endpoints ?? {}) };

  const urlFor = (path: string) => `${baseUrl}${path}`;
  const request = <T>(path: string, init: RequestInit) =>
    fetchJson<T>(fetchImpl, urlFor(path), init);

  return {
    getAccount: () =>
      request<AomiBackendAccountResponse>(endpoints.accountPath, {
        method: "GET",
      }),
    updateAccount: (body: {
      displayName?: string | null;
      avatarUrl?: string | null;
    }) =>
      request<AomiBackendAccountResponse>(endpoints.accountPath, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
      }),
    deleteAccount: () =>
      request<AomiBackendDeleteAccountResponse>(endpoints.accountPath, {
        method: "DELETE",
      }),
    signOut: () => request(endpoints.signOutPath, { method: "POST" }),
    exchangeProviderCredential: (
      credential: AomiAccountCredential,
      options: { hasAccount: boolean },
    ) =>
      request<AomiBackendProviderExchangeResponse>(
        options.hasAccount
          ? endpoints.existingSessionProviderExchangePath
          : endpoints.newSessionProviderExchangePath,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(credential),
        },
      ),
    getWalletLinkNonce: (input: { address: string; chainId: number }) => {
      const params = new URLSearchParams({
        address: input.address,
        chainId: String(input.chainId),
      });
      return request<AomiBackendNonceResponse>(
        `${endpoints.walletLinkPath}?${params.toString()}`,
        { method: "GET" },
      );
    },
    linkWallet: (body: unknown) =>
      request<AomiBackendLinkWalletResponse>(endpoints.walletLinkPath, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
      }),
    updateWallet: (walletId: string, body: { label?: string | null }) =>
      request(endpoints.walletPath(walletId), {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
      }),
    updateAuthIdentity: (
      identityId: string,
      body: { displayLabel?: string | null },
    ) =>
      request(endpoints.identityPath(identityId), {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
      }),
    unlinkWallet: (walletId: string) =>
      request(endpoints.walletPath(walletId), { method: "DELETE" }),
    unlinkAuthIdentity: (identityId: string) =>
      request(endpoints.identityPath(identityId), { method: "DELETE" }),
    createSiweNonce: (body: { walletAddress: string; chainId: number }) =>
      request<AomiBackendNonceResponse>(endpoints.siweNoncePath, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
      }),
    verifySiwe: (body: {
      message: string;
      signature: string;
      walletAddress: string;
      chainId: number;
    }) =>
      request(endpoints.siweVerifyPath, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
      }),
  };
}

async function fetchJson<T>(
  fetchImpl: typeof fetch,
  url: string,
  init: RequestInit,
): Promise<T> {
  const response = await fetchImpl(url, {
    credentials: "include",
    ...init,
    headers: {
      Accept: "application/json",
      ...(init.headers ?? {}),
    },
  });
  if (!response.ok) {
    const error = await response.json().catch(() => null);
    const code = extractErrorCode(error);
    throw new Error(formatAccountRequestError(response.status, code));
  }
  return (await response.json()) as T;
}

function extractErrorCode(error: unknown): string | null {
  if (!error || typeof error !== "object") return null;
  if ("error" in error && error.error) return String(error.error);
  if ("message" in error && error.message) return String(error.message);
  return null;
}

function formatAccountRequestError(
  status: number,
  code: string | null,
): string {
  if (status === 409 && code === "already_linked_to_another_account") {
    return "This wallet or sign-in method is already linked to another Aomi account. Sign in to that account to unlink it first.";
  }
  return code ?? `Request failed: ${status}`;
}

function normalizeBaseUrl(baseUrl?: string): string {
  return baseUrl?.replace(/\/+$/, "") ?? "";
}

"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type { AuthRuntime, SvmWalletRuntime } from "../composer/types";
import type { EvmWalletRuntime } from "../runtime/evm/wallet-runtime";
import { brandDisplayName } from "../runtime/evm/brands";
import type { AccountRuntime, AccountWallet } from "./types";
import type { AomiAccount, WalletFamily } from "../types";
import {
  createAomiBackendAccountClient,
  type AomiBackendAccountResponse,
  type AomiBackendNonceResponse,
} from "./aomi-backend-client";

export type AomiBackendAccountConfig = {
  mode: "aomi-backend";
  baseUrl?: string;
  authDomain?: string;
  authUri?: string;
};

const CREDENTIAL_EXCHANGE_FAILURE_COOLDOWN_MS = 30_000;

export function useAomiBackendAccountRuntime(input: {
  enabled: boolean;
  baseUrl?: string;
  authDomain?: string;
  authUri?: string;
  auth: AuthRuntime;
  evm: EvmWalletRuntime;
  svm?: SvmWalletRuntime;
}): AccountRuntime {
  const accountClient = useMemo(
    () => createAomiBackendAccountClient({ baseUrl: input.baseUrl }),
    [input.baseUrl],
  );
  const authMessageConfig = useMemo(
    () =>
      resolveAuthMessageConfig({
        baseUrl: input.baseUrl,
        authDomain: input.authDomain,
        authUri: input.authUri,
      }),
    [input.authDomain, input.authUri, input.baseUrl],
  );
  const [account, setAccount] = useState<AomiBackendAccountResponse | null>(
    null,
  );
  const [status, setStatus] = useState<AccountRuntime["status"]>(
    input.enabled ? "loading" : "disabled",
  );
  const [errorVersion, setErrorVersion] = useState(0);
  const siweInFlight = useRef<string | null>(null);
  const accountCreateInFlight = useRef<string | null>(null);
  const signedOutEvmKey = useRef<string | null>(null);
  const signedOutCredentialKey = useRef<string | null>(null);
  const credentialInFlight = useRef<string | null>(null);
  const credentialExchanged = useRef<string | null>(null);
  const providerSessionAttempted = useRef<string | null>(null);
  const credentialFailed = useRef<{
    attemptKey: string;
    failedAt: number;
  } | null>(null);

  const refresh = useCallback(async () => {
    if (!input.enabled) return;
    setStatus((current) => (current === "ready" ? current : "loading"));
    try {
      const next = await accountClient.getAccount();
      setAccount(next);
      setStatus("ready");
    } catch {
      setStatus("error");
      setErrorVersion((version) => version + 1);
    }
  }, [accountClient, input.enabled]);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  useEffect(() => {
    if (input.auth.status !== "authenticated") {
      signedOutCredentialKey.current = null;
      credentialInFlight.current = null;
      credentialExchanged.current = null;
      providerSessionAttempted.current = null;
      credentialFailed.current = null;
    }
  }, [input.auth.status, input.auth.subject]);

  const activeEvmAddress =
    input.evm.activeEvmConnection?.address ?? input.evm.activeAccount?.address;
  const activeEvmChainId =
    input.evm.activeEvmConnection?.chainId ?? input.evm.activeAccount?.chainId;

  useEffect(() => {
    if (
      !input.enabled ||
      status === "error" ||
      account === null ||
      account.user ||
      !hasAuthMessageConfig(authMessageConfig)
    ) {
      return;
    }
    if (!activeEvmAddress || !activeEvmChainId || !input.evm.signMessageAsync) {
      signedOutEvmKey.current = null;
      return;
    }
    const key = `${activeEvmAddress}:${activeEvmChainId}`;
    const authKey = authSessionKey(input.auth);
    if (
      input.auth.status === "authenticated" &&
      input.auth.getCredential &&
      providerSessionAttempted.current !== authKey
    ) {
      return;
    }
    if (signedOutEvmKey.current === key) return;
    if (siweInFlight.current === key) return;
    if (accountCreateInFlight.current) return;
    siweInFlight.current = key;
    accountCreateInFlight.current = `siwe:${key}`;
    signInWithActiveEvmWallet({
      address: activeEvmAddress as `0x${string}`,
      accountClient,
      chainId: activeEvmChainId,
      signMessageAsync: input.evm.signMessageAsync as (args: {
        message: string;
      }) => Promise<`0x${string}`>,
      messageConfig: authMessageConfig,
    })
      .then(refresh)
      .catch(() => {
        // A rejected/failed auto-SIWE attempt must not block provider-token
        // sign-in; suppress repeat prompts for this wallet and keep runtime live.
        signedOutEvmKey.current = key;
        setStatus("ready");
        setErrorVersion((version) => version + 1);
      })
      .finally(() => {
        siweInFlight.current = null;
        if (accountCreateInFlight.current === `siwe:${key}`) {
          accountCreateInFlight.current = null;
        }
      });
  }, [
    account,
    activeEvmAddress,
    activeEvmChainId,
    accountClient,
    authMessageConfig,
    input.enabled,
    input.evm.signMessageAsync,
    refresh,
    status,
  ]);

  useEffect(() => {
    if (
      !input.enabled ||
      status === "error" ||
      input.auth.status !== "authenticated"
    ) {
      return;
    }
    if (!input.auth.getCredential) return;
    let cancelled = false;
    async function exchange() {
      const authKey = authSessionKey(input.auth);
      const credential = await input.auth.getCredential?.().catch(() => null);
      if (!credential || cancelled) {
        if (!cancelled) providerSessionAttempted.current = authKey;
        return;
      }
      const key = credentialKey(credential);
      const signedOutKey = authCredentialKey(input.auth, key);
      if (!account?.user && signedOutCredentialKey.current === signedOutKey) {
        providerSessionAttempted.current = authKey;
        return;
      }
      // Any provider credential is exchangeable, in any order: link to the
      // current account if one exists, otherwise create one. No policy gate.
      const hasAccount = Boolean(account?.user);
      const attemptKey = `${hasAccount ? "link" : "session"}:${account?.user?.id ?? "new"}:${key}`;
      if (!hasAccount && accountCreateInFlight.current) return;
      const failedAttempt = credentialFailed.current;
      if (
        credentialInFlight.current === attemptKey ||
        credentialExchanged.current === attemptKey ||
        (failedAttempt?.attemptKey === attemptKey &&
          Date.now() - failedAttempt.failedAt <
            CREDENTIAL_EXCHANGE_FAILURE_COOLDOWN_MS)
      ) {
        return;
      }
      credentialInFlight.current = attemptKey;
      if (!hasAccount) accountCreateInFlight.current = attemptKey;
      try {
        const result = await accountClient.exchangeProviderCredential(
          credential,
          { hasAccount },
        );
        credentialExchanged.current = attemptKey;
        if (result.account) setAccount(result.account);
        await refresh();
      } catch {
        credentialFailed.current = { attemptKey, failedAt: Date.now() };
        setStatus("ready");
        setErrorVersion((version) => version + 1);
      } finally {
        providerSessionAttempted.current = authKey;
        if (credentialInFlight.current === attemptKey) {
          credentialInFlight.current = null;
        }
        if (accountCreateInFlight.current === attemptKey) {
          accountCreateInFlight.current = null;
        }
      }
    }
    void exchange();
    return () => {
      cancelled = true;
    };
  }, [
    account?.user,
    accountClient,
    input.auth,
    input.enabled,
    refresh,
    status,
  ]);

  const liveAccounts = useMemo(
    () => [
      ...input.evm.accounts(Date.now()),
      ...(input.svm?.accounts(Date.now()) ?? []),
    ],
    // `errorVersion` intentionally re-samples live wallet adapters after a
    // failed auth/account side effect, because the adapter object identities
    // can stay stable while their internal account snapshots changed.
    [errorVersion, input.evm, input.svm],
  );

  const liveWalletKeys = useMemo(() => {
    const keys = new Set<string>();
    for (const acct of liveAccounts) {
      keys.add(walletAccountKey(acct.family, acct.address));
    }
    return keys;
  }, [liveAccounts]);

  const wallets = useMemo(
    () =>
      (account?.wallets ?? []).map((wallet) => {
        const key = walletAccountKey(wallet.family, wallet.address);
        return {
          ...normalizeAccountWalletProvider(wallet, liveAccounts),
          capability: liveWalletKeys.has(key) ? "write" : "read",
        } satisfies AccountWallet;
      }),
    [account?.wallets, liveAccounts, liveWalletKeys],
  );

  return {
    status: input.enabled ? status : "disabled",
    user: account?.user ?? undefined,
    linkedAccounts: account?.linkedAccounts ?? [],
    wallets,
    refresh,
    signOut: async () => {
      if (activeEvmAddress && activeEvmChainId) {
        signedOutEvmKey.current = `${activeEvmAddress}:${activeEvmChainId}`;
      }
      if (input.auth.status === "authenticated" && input.auth.getCredential) {
        const credential = await input.auth.getCredential().catch(() => null);
        if (credential) {
          signedOutCredentialKey.current = authCredentialKey(
            input.auth,
            credentialKey(credential),
          );
        }
      }
      credentialInFlight.current = null;
      credentialExchanged.current = null;
      providerSessionAttempted.current = null;
      credentialFailed.current = null;
      await accountClient.signOut();
      setAccount({
        user: null,
        linkedAccounts: [],
        wallets: [],
        session: null,
      });
      setStatus("ready");
    },
    deleteAccount: async () => {
      if (activeEvmAddress && activeEvmChainId) {
        signedOutEvmKey.current = `${activeEvmAddress}:${activeEvmChainId}`;
      }
      if (input.auth.status === "authenticated" && input.auth.getCredential) {
        const credential = await input.auth.getCredential().catch(() => null);
        if (credential) {
          signedOutCredentialKey.current = authCredentialKey(
            input.auth,
            credentialKey(credential),
          );
        }
      }
      credentialInFlight.current = null;
      credentialExchanged.current = null;
      providerSessionAttempted.current = null;
      credentialFailed.current = null;
      await accountClient.deleteAccount();
      setAccount({
        user: null,
        linkedAccounts: [],
        wallets: [],
        session: null,
      });
      setStatus("ready");
    },
    updateAccount: async ({ displayName, avatarUrl }) => {
      await accountClient.updateAccount({ displayName, avatarUrl });
      await refresh();
    },
    linkWallet: async (wallet) => {
      if (
        wallet.family !== "evm" ||
        (!input.evm.signMessageForAccount && !input.evm.signMessageAsync)
      ) {
        throw new Error("Wallet linking requires an active EVM signer");
      }
      const chainId = wallet.chainId ?? activeEvmChainId;
      if (!chainId) throw new Error("Wallet linking requires an EVM chain id");
      if (!account?.user) {
        const accountId = wallet.accountId;
        const signMessageForAccount = input.evm.signMessageForAccount;
        await signInWithEvmWallet({
          accountClient,
          address: wallet.address as `0x${string}`,
          chainId,
          signMessage:
            accountId && signMessageForAccount
              ? (message) =>
                  signMessageForAccount({
                    accountId,
                    chainId,
                    message,
                  })
              : (message) =>
                  signMessageWithActiveEvm(input.evm.signMessageAsync, message),
          messageConfig: authMessageConfig,
        });
        await refresh();
        return;
      }
      const nonceResult = await accountClient.getWalletLinkNonce({
        address: wallet.address,
        chainId,
      });
      const message = buildWalletLinkMessage({
        address: wallet.address,
        chainId,
        nonce: nonceResult.nonce,
        ...messageConfigFromNonce(nonceResult, authMessageConfig),
      });
      const signature =
        wallet.accountId && input.evm.signMessageForAccount
          ? await input.evm.signMessageForAccount({
              accountId: wallet.accountId,
              chainId,
              message,
            })
          : await signMessageWithActiveEvm(input.evm.signMessageAsync, message);
      // Name the label after the wallet actually being linked, not whichever
      // wallet happens to be the active EVM signer — linking MetaMask while a
      // Privy smart wallet is active must read "MetaMask N", not "Privy …".
      const defaultLabel = buildDefaultWalletLabel({
        walletName: resolveLinkedWalletName({
          accounts: input.evm.accounts(Date.now()),
          accountId: wallet.accountId,
          address: wallet.address,
          fallbackWalletName: input.evm.activeEvmConnection?.walletName,
        }),
        existingWallets: account?.wallets ?? [],
        family: wallet.family,
      });
      const body = {
        ...wallet,
        chainId,
        label: defaultLabel,
        message,
        signature,
        nonce: nonceResult.nonce,
      };
      const result = await accountClient.linkWallet(body);
      if (result.account) setAccount(result.account);
      await refresh();
    },
    updateWallet: async ({ walletId, label }) => {
      await accountClient.updateWallet(walletId, { label });
      await refresh();
    },
    updateAuthIdentity: async ({ identityId, displayLabel }) => {
      await accountClient.updateAuthIdentity(identityId, { displayLabel });
      await refresh();
    },
    unlinkWallet: async (walletId) => {
      await accountClient.unlinkWallet(walletId);
      await refresh();
    },
    unlinkAuthIdentity: async (identityId) => {
      await accountClient.unlinkAuthIdentity(identityId);
      await refresh();
    },
  };
}

function walletAccountKey(family: WalletFamily, address: string): string {
  return family === "evm"
    ? `${family}:${address.toLowerCase()}`
    : `${family}:${address}`;
}

export function normalizeAccountWalletProvider(
  wallet: AccountWallet,
  liveAccounts: readonly Pick<
    AomiAccount,
    "family" | "address" | "provider" | "walletKind"
  >[],
): AccountWallet {
  const liveAccount = liveAccounts.find(
    (account) =>
      account.family === wallet.family &&
      walletAccountKey(account.family, account.address) ===
        walletAccountKey(wallet.family, wallet.address),
  );
  const provider = liveAccount?.provider;
  const walletKind = liveAccount?.walletKind;
  if (
    provider &&
    walletKind &&
    walletKind !== "embedded" &&
    walletKind !== "smart_account"
  ) {
    return wallet;
  }
  const inferredProvider =
    provider ?? providerLinkedWalletVia(wallet.linkedVia);
  if (!inferredProvider) return wallet;

  return {
    ...wallet,
    provider: wallet.provider ?? inferredProvider,
    kind:
      walletKind === "embedded" || walletKind === "smart_account"
        ? walletKind
        : (wallet.kind ?? "embedded"),
  };
}

function providerLinkedWalletVia(linkedVia: AccountWallet["linkedVia"]) {
  if (
    linkedVia === "siwe" ||
    linkedVia === "siws" ||
    linkedVia === "challenge" ||
    linkedVia === "import" ||
    linkedVia === "observed" ||
    linkedVia === "migration"
  ) {
    return null;
  }
  return linkedVia;
}

function credentialKey(credential: unknown): string {
  return (JSON.stringify(credential) ?? "").slice(0, 96);
}

function authCredentialKey(
  auth: Pick<AuthRuntime, "provider" | "subject">,
  key: string,
): string {
  return `${auth.provider}:${auth.subject ?? "unknown"}:${key}`;
}

function authSessionKey(
  auth: Pick<AuthRuntime, "provider" | "subject">,
): string {
  return `${auth.provider}:${auth.subject ?? "unknown"}`;
}

/**
 * Resolve the brand name of the wallet being linked from the live EVM accounts,
 * matching by stable account id first and address second. Falls back to the
 * caller-supplied active-connection name only when the linked wallet isn't in
 * the live set — so a default label is always brand-correct for the wallet the
 * user actually picked, even when a different wallet is the active signer.
 */
export function resolveLinkedWalletName(input: {
  accounts: ReadonlyArray<{
    id: string;
    address?: string;
    walletName?: string;
  }>;
  accountId?: string;
  address: string;
  fallbackWalletName?: string;
}): string | undefined {
  const target = input.address.toLowerCase();
  const match = input.accounts.find(
    (candidate) =>
      (input.accountId !== undefined && candidate.id === input.accountId) ||
      candidate.address?.toLowerCase() === target,
  );
  return match?.walletName ?? input.fallbackWalletName;
}

/**
 * Build a first-link default label like "Rabby 1" / "MetaMask 2" so the
 * account-management row is never blank before the user renames it. Only used
 * as the initial value — the account service persists labels as
 * `auth_providers.provider_metadata.display_label` and keeps the stored one on
 * re-link, so user renames stick.
 */
export function buildDefaultWalletLabel(input: {
  walletName?: string | null;
  existingWallets: readonly AccountWallet[];
  family: WalletFamily;
}): string {
  const brand = brandDisplayName(input.walletName);
  const sameBrand = input.existingWallets.filter(
    (wallet) =>
      wallet.family === input.family &&
      wallet.label?.toLowerCase().startsWith(brand.toLowerCase()),
  ).length;
  return `${brand} ${sameBrand + 1}`;
}

async function signMessageWithActiveEvm(
  signMessageAsync: EvmWalletRuntime["signMessageAsync"],
  message: string,
): Promise<`0x${string}`> {
  if (!signMessageAsync) {
    throw new Error("Wallet linking requires an active EVM signer");
  }
  return (await (
    signMessageAsync as (args: { message: string }) => Promise<`0x${string}`>
  )({ message })) as `0x${string}`;
}

async function signInWithActiveEvmWallet(input: {
  accountClient: ReturnType<typeof createAomiBackendAccountClient>;
  address: `0x${string}`;
  chainId: number;
  signMessageAsync: (args: { message: string }) => Promise<`0x${string}`>;
  messageConfig: AuthMessageConfig;
}): Promise<void> {
  await signInWithEvmWallet({
    accountClient: input.accountClient,
    address: input.address,
    chainId: input.chainId,
    signMessage: (message) => input.signMessageAsync({ message }),
    messageConfig: input.messageConfig,
  });
}

async function signInWithEvmWallet(input: {
  accountClient: ReturnType<typeof createAomiBackendAccountClient>;
  address: `0x${string}`;
  chainId: number;
  signMessage: (message: string) => Promise<`0x${string}`>;
  messageConfig: AuthMessageConfig;
}): Promise<void> {
  const nonceResult = await input.accountClient.createSiweNonce({
    walletAddress: input.address,
    chainId: input.chainId,
  });
  const message = buildSiweMessage({
    address: input.address,
    chainId: input.chainId,
    nonce: nonceResult.nonce,
    ...messageConfigFromNonce(nonceResult, input.messageConfig),
  });
  const signature = await input.signMessage(message);
  await input.accountClient.verifySiwe({
    message,
    signature,
    walletAddress: input.address,
    chainId: input.chainId,
  });
}

export type AuthMessageConfig = {
  domain: string;
  uri: string;
};

export function resolveAuthMessageConfig(input: {
  baseUrl?: string;
  authDomain?: string;
  authUri?: string;
}): AuthMessageConfig {
  const base = absoluteUrl(input.baseUrl);
  const fallbackOrigin =
    base?.origin ??
    (typeof window !== "undefined" ? window.location.origin : "");
  const fallbackDomain =
    base?.host ?? (typeof window !== "undefined" ? window.location.host : "");
  return {
    domain: normalizeDomain(input.authDomain) ?? fallbackDomain,
    uri: normalizeUri(input.authUri) ?? fallbackOrigin,
  };
}

export function buildSiweMessage(input: {
  address: string;
  chainId: number;
  nonce: string;
  domain: string;
  uri: string;
}): string {
  const { domain, uri } = requireAuthMessageConfig(input);
  return `${domain} wants you to sign in with your Ethereum account:
${input.address}

Sign in to Aomi.

URI: ${uri}
Version: 1
Chain ID: ${input.chainId}
Nonce: ${input.nonce}
Issued At: ${new Date().toISOString()}`;
}

export function buildWalletLinkMessage(input: {
  address: string;
  chainId: number;
  nonce: string;
  domain: string;
  uri: string;
}): string {
  const { domain, uri } = requireAuthMessageConfig(input);
  return `${domain} wants to link this wallet to your Aomi account:
${input.address}

Only sign this message if you want this wallet attached to the current Aomi account.

URI: ${uri}
Version: 1
Chain ID: ${input.chainId}
Nonce: ${input.nonce}
Issued At: ${new Date().toISOString()}`;
}

function messageConfigFromNonce(
  nonce: AomiBackendNonceResponse,
  fallback: AuthMessageConfig,
): AuthMessageConfig {
  return completeAuthMessageConfig({
    domain: normalizeDomain(nonce.domain) ?? normalizeDomain(fallback.domain),
    uri: normalizeUri(nonce.uri) ?? normalizeUri(fallback.uri),
  });
}

function browserAuthMessageConfig(): AuthMessageConfig {
  if (typeof window === "undefined") {
    return { domain: "", uri: "" };
  }
  return {
    domain: window.location.host,
    uri: window.location.origin,
  };
}

function requireAuthMessageConfig(input: AuthMessageConfig): AuthMessageConfig {
  return completeAuthMessageConfig(input);
}

function completeAuthMessageConfig(
  input: Partial<AuthMessageConfig>,
): AuthMessageConfig {
  const browserFallback = browserAuthMessageConfig();
  const uri =
    normalizeUri(input.uri) ??
    normalizeUri(browserFallback.uri) ??
    deriveUriFromDomain(input.domain) ??
    "http://localhost";
  const domain =
    normalizeDomain(input.domain) ??
    normalizeDomain(uri) ??
    normalizeDomain(browserFallback.domain) ??
    "localhost";
  return { domain, uri };
}

function hasAuthMessageConfig(input: Partial<AuthMessageConfig>): boolean {
  const browserFallback = browserAuthMessageConfig();
  const domain =
    normalizeDomain(input.domain) ?? normalizeDomain(browserFallback.domain);
  const uri =
    normalizeUri(input.uri) ??
    normalizeUri(browserFallback.uri) ??
    deriveUriFromDomain(domain);
  return Boolean(domain && uri);
}

function absoluteUrl(value: string | undefined): URL | null {
  if (!value) return null;
  try {
    return new URL(value);
  } catch {
    return null;
  }
}

function normalizeDomain(value: string | undefined): string | undefined {
  const trimmed = value?.trim();
  if (!trimmed) return undefined;
  try {
    const host = new URL(trimmed).host.trim();
    if (host) return host;
  } catch {
    // Fall through to authority parsing below.
  }
  return (
    trimmed
      .replace(/^[a-z][a-z0-9+.-]*:\/\//i, "")
      .replace(/\/.*$/, "")
      .trim() || undefined
  );
}

function normalizeUri(value: string | undefined): string | undefined {
  const trimmed = value?.trim().replace(/\/+$/, "");
  if (!trimmed) return undefined;
  try {
    const url = new URL(trimmed);
    if (url.protocol !== "http:" && url.protocol !== "https:") {
      return undefined;
    }
    return url.toString().replace(/\/+$/, "");
  } catch {
    return undefined;
  }
}

function deriveUriFromDomain(value: string | undefined): string | undefined {
  const domain = normalizeDomain(value);
  if (!domain) return undefined;
  return domain.includes("localhost") || domain.startsWith("127.")
    ? `http://${domain}`
    : `https://${domain}`;
}

"use client";

import type { AuthRuntime, SvmWalletRuntime } from "../composer/types";
import type { AccountConfig } from "../config/types";
import type { EvmWalletRuntime } from "../runtime/evm/wallet-runtime";
import { useAomiBackendAccountRuntime } from "./aomi-backend-runtime";
import { DISABLED_ACCOUNT_RUNTIME } from "./disabled-runtime";
import type { AccountRuntime } from "./types";

export function useResolvedAccountRuntime(input: {
  account?: AccountConfig;
  auth: AuthRuntime;
  evm: EvmWalletRuntime;
  svm?: SvmWalletRuntime;
}): AccountRuntime {
  const accountConfig =
    input.account !== false && input.account?.mode === "aomi-backend"
      ? input.account
      : null;
  const runtime = useAomiBackendAccountRuntime({
    enabled: Boolean(accountConfig),
    baseUrl: accountConfig?.baseUrl,
    authDomain: accountConfig?.authDomain,
    authUri: accountConfig?.authUri,
    auth: input.auth,
    evm: input.evm,
    svm: input.svm,
  });
  return accountConfig ? runtime : DISABLED_ACCOUNT_RUNTIME;
}

"use client";

import { useEffect, useMemo, useState } from "react";
import { UserState, useUser } from "@aomi-labs/react";
import { AomiWalletKitContextProvider } from "../context";
import type { AomiAccount, AomiWalletKit } from "../types";
import { EVM_IDENTITY_GRACE_MS, REGISTRY_STORAGE_KEY } from "../registry/types";
import { walletDebug } from "../wallet-debug";
import { DISABLED_ACCOUNT_RUNTIME } from "../account/disabled-runtime";
import { buildWalletKitAccounts } from "../accounts";
import { buildWalletKitIdentity } from "./build-identity";
import { buildWalletKitActions } from "./build-wallet-kit-actions";
import { mergeWalletRows } from "./merge-wallet-rows";
import type { AomiWalletKitComposerProps } from "./types";

export function AomiWalletKitComposer({
  children,
  auth,
  evm,
  svm,
  execution,
  account = DISABLED_ACCOUNT_RUNTIME,
  additionalEvmWalletOptions = [],
  transformEvmIdentity,
  transformAccounts,
  canManageAccount,
  supportedChains,
}: AomiWalletKitComposerProps) {
  const { user } = useUser();
  const userAAMode = UserState.aaMode(user);
  const userSmartAccount4337 = UserState.SmartAccount4337(user);
  const userDelegation7702 = UserState.Delegation7702(user);
  const [evmIdentityGraceVersion, bumpEvmIdentityGrace] = useState(0);
  const { registryStore, registryState } = evm;

  const registryEvmIdentity = useMemo(() => {
    const identity = evm.identity(Date.now());
    return transformEvmIdentity ? transformEvmIdentity(identity) : identity;
  }, [evmIdentityGraceVersion, evm, transformEvmIdentity]);

  const gracefulEvmIdentity = {
    identity: registryEvmIdentity,
    disconnectedAt: registryState.evmGrace.disconnectedAt,
    usingCachedIdentity: Boolean(
      registryState.evmGrace.disconnectedAt && registryEvmIdentity.address,
    ),
  };

  useEffect(() => {
    if (
      !gracefulEvmIdentity.usingCachedIdentity ||
      gracefulEvmIdentity.disconnectedAt === null
    ) {
      return;
    }

    const elapsed = Date.now() - gracefulEvmIdentity.disconnectedAt;
    const timeout = window.setTimeout(
      () => bumpEvmIdentityGrace((version) => version + 1),
      Math.max(0, EVM_IDENTITY_GRACE_MS - elapsed) + 1,
    );
    return () => window.clearTimeout(timeout);
  }, [
    gracefulEvmIdentity.disconnectedAt,
    gracefulEvmIdentity.usingCachedIdentity,
  ]);

  useEffect(() => {
    if (registryState.phase !== "stable") return;
    const registryAddress =
      registryState.activeByFamily.evm?.address.toLowerCase() ?? null;
    const liveAddress =
      gracefulEvmIdentity.identity.address?.toLowerCase() ?? null;
    if (registryAddress === liveAddress) return;
    walletDebug("registry:shadow-diff", {
      registryAddress,
      liveAddress,
      registryActive: registryState.activeByFamily.evm,
    });
  }, [
    gracefulEvmIdentity.identity.address,
    registryState.activeByFamily.evm,
    registryState.phase,
  ]);

  const adapter = useMemo<AomiWalletKit>(() => {
    const address = gracefulEvmIdentity.identity.address;
    const effectiveChainId = gracefulEvmIdentity.identity.chainId;
    const svmIdentity = svm?.identity(Date.now());
    const registryEvmConnected = registryState.connections.some(
      (connection) => connection.family === "evm",
    );
    const isConnected = Boolean(
      auth.status === "authenticated" ||
      registryEvmConnected ||
      address ||
      svmIdentity?.address,
    );
    const isBooting = auth.status === "booting" && !isConnected;
    const solanaWalletDescriptors =
      svm?.options.map((option) => ({
        name: option.label,
        installed: Boolean(option.installed),
        ready: option.ready !== false && option.status !== "unavailable",
        iconUrl: option.iconUrl,
      })) ?? [];
    const accounts = buildWalletKitAccounts({
      accounts: [
        ...evm.accounts(Date.now()),
        ...(svm?.accounts(Date.now()) ?? []),
      ],
      accountWallets: account.wallets,
      transformAccounts,
      canManageAccount,
    });
    const evmWalletOptions = [...evm.options, ...additionalEvmWalletOptions];
    const svmWalletOptions =
      svm?.options.map((option) => ({
        ...option,
        family: "svm" as const,
        kind: "solana" as const,
      })) ?? [];
    const walletModalRows = mergeWalletRows({
      accounts,
      storedWallets: account.wallets,
      canLinkWallet: Boolean(account.linkWallet),
      auth,
      options: [...evmWalletOptions, ...svmWalletOptions, ...auth.methods],
    });
    const actions = buildWalletKitActions({
      accounts,
      auth,
      evm,
      svm,
      execution,
      registryStore,
      evmAddress: address,
      registryEvmConnected,
      svmIdentity,
    });
    const hasAnyDisconnectablePath = Boolean(
      registryState.connections.length > 0 || svmIdentity?.address,
    );
    const identity = buildWalletKitIdentity({
      auth,
      address,
      chainId: effectiveChainId ?? undefined,
      isBooting,
      isConnected,
      svm,
      aa: {
        aaMode: userAAMode ?? "none",
        SmartAccount4337: userSmartAccount4337 ?? undefined,
        Delegation7702: userDelegation7702 ?? undefined,
      },
      sponsorship: {
        sponsored: execution.sponsorship.sponsored,
        sponsorProvider: execution.sponsorship.sponsorProvider,
        sponsorAccount: execution.sponsorship.sponsorAccount,
      },
      walletName: gracefulEvmIdentity.identity.walletName,
      walletSource: gracefulEvmIdentity.identity.walletSource,
    });
    return {
      identity,
      isReady: !isBooting,
      isSwitchingChain: evm.isSwitchingChain,
      canConnect:
        Boolean(auth.canOpenModal) ||
        Boolean(solanaWalletDescriptors.length) ||
        Boolean(evmWalletOptions.length),
      canOpenAccountUI:
        Boolean(auth.openAccountUI) &&
        auth.status === "authenticated" &&
        identity.isConnected,
      canDisconnect: hasAnyDisconnectablePath,
      accounts,
      walletModalRows,
      accountStatus: account.status,
      accountUser: account.user,
      accountLinkedAccounts: account.linkedAccounts,
      accountWallets: account.wallets,
      signOutAccount: account.signOut,
      deleteAccount: account.deleteAccount,
      updateAccount: account.updateAccount,
      linkWallet: account.linkWallet,
      updateLinkedAccount: account.updateAuthIdentity,
      updateLinkedWallet: account.updateWallet,
      unlinkLinkedWallet: account.unlinkWallet,
      unlinkLinkedAccount: account.unlinkAuthIdentity,
      selectAccount: actions.selectAccount,
      evmWallets: evmWalletOptions,
      connectEvmWallet: actions.connectEvmWallet,
      socialLoginOptions: auth.methods,
      connectSocial: actions.connectSocial,
      solanaWallets: solanaWalletDescriptors,
      connectSolanaWallet: actions.connectSolanaWallet,
      supportedChains,
      supportedNetworks: {
        evm: supportedChains,
        solana: svm?.supportedNetworks ?? [],
      },
      solanaNetworkSwitchRequiresReconnect: Boolean(svmIdentity?.address),
      connect: actions.connect,
      disconnect: actions.disconnect,
      openAccountUI: actions.openAccountUI,
      switchChain: actions.switchChain,
      selectNetwork: actions.selectNetwork,
      sendTransaction: execution.evm.sendTransaction,
      signTypedData: execution.evm.signTypedData,
      signMessage: execution.evm.signMessage,
      getAccountCredential:
        auth.status === "authenticated" ? auth.getCredential : undefined,
      signSolanaTransaction: svm?.execution.signSolanaTransaction,
      signSolanaMessage: svm?.execution.signSolanaMessage,
      sendSolanaTransaction: svm?.execution.sendSolanaTransaction,
      signAndSendSolanaTransaction: svm?.execution.signAndSendSolanaTransaction,
      solanaRpcHttpUrl: svm?.execution.solanaRpcHttpUrl,
      solanaRpcWsUrl: svm?.execution.solanaRpcWsUrl,
    };
  }, [
    auth,
    account.wallets,
    account.linkedAccounts,
    account.status,
    account.deleteAccount,
    account.updateAccount,
    account.linkWallet,
    account.updateAuthIdentity,
    account.unlinkWallet,
    account.unlinkAuthIdentity,
    account.updateWallet,
    account.user,
    additionalEvmWalletOptions,
    canManageAccount,
    evm,
    execution,
    gracefulEvmIdentity.identity.address,
    gracefulEvmIdentity.identity.chainId,
    gracefulEvmIdentity.identity.walletName,
    registryStore,
    svm,
    supportedChains,
    transformAccounts,
    userAAMode,
    userDelegation7702,
    userSmartAccount4337,
  ]);

  return (
    <AomiWalletKitContextProvider value={adapter}>
      {children}
    </AomiWalletKitContextProvider>
  );
}

"use client";

import {
  AOMI_SESSION_BOOTING_IDENTITY,
  AOMI_SESSION_DISCONNECTED_IDENTITY,
  formatAuthMethod,
  formatWalletAddress,
  formatWalletProvider,
} from "../identity";
import type { AomiSessionIdentity } from "../types";
import type { AuthRuntime, SvmWalletRuntime } from "./types";

export function buildWalletKitIdentity({
  auth,
  address,
  chainId,
  isBooting,
  isConnected,
  svm,
  aa,
  sponsorship,
  walletName,
  walletSource,
}: {
  auth: AuthRuntime;
  address?: string;
  chainId?: number;
  isBooting: boolean;
  isConnected: boolean;
  svm?: SvmWalletRuntime;
  aa: Pick<AomiSessionIdentity, "aaMode" | "SmartAccount4337" | "Delegation7702">;
  sponsorship: Pick<
    AomiSessionIdentity,
    "sponsored" | "sponsorProvider" | "sponsorAccount"
  >;
  walletName?: string;
  walletSource?: AomiSessionIdentity["walletSource"];
}): AomiSessionIdentity {
  const svmIdentity = svm?.identity(Date.now());
  const svmAddress = svmIdentity?.address;
  const svmTransport = svmIdentity?.transport;
  const svmCapabilities = svmIdentity?.capabilities;
  const baseSvm = {
    svmAddress,
    svmCluster: svmIdentity?.cluster,
    svmWalletName: svmIdentity?.walletName,
    svmTransport: svmAddress ? svmTransport : undefined,
    svmCapabilities,
    solanaCluster: svmIdentity?.cluster,
    solanaWalletName: svmIdentity?.walletName,
    solanaTransport: svmAddress ? svmTransport : undefined,
    solanaCapabilities: svmCapabilities,
  };

  if (isBooting) {
    return {
      ...AOMI_SESSION_BOOTING_IDENTITY,
      chainId,
      ...baseSvm,
    };
  }

  if (isConnected && auth.primaryLabel) {
    return {
      status: "connected",
      isConnected: true,
      address,
      walletKind: "eoa",
      ...aa,
      ...sponsorship,
      chainId,
      sessionProvider: auth.sessionProvider,
      embeddedProvider: auth.embeddedProvider,
      walletSource:
        walletSource ??
        (address && auth.embeddedProvider ? "embedded" : undefined),
      walletProvider: auth.legacyWalletProvider,
      walletProviderSubject: auth.subject,
      authMethod: auth.authMethod,
      authProvider: auth.authMethod,
      authValue: auth.authValue,
      primaryLabel: auth.primaryLabel,
      secondaryLabel:
        formatAuthMethod(auth.authMethod) ??
        formatWalletProvider(auth.provider),
      ...baseSvm,
    };
  }

  if (isConnected && address) {
    return {
      status: "connected",
      isConnected: true,
      address,
      walletKind: "eoa",
      ...aa,
      ...sponsorship,
      chainId,
      sessionProvider: auth.sessionProvider,
      embeddedProvider: auth.embeddedProvider,
      walletSource:
        walletSource ?? (auth.embeddedProvider ? "embedded" : "injected"),
      walletProvider: auth.legacyWalletProvider,
      walletProviderSubject: auth.subject,
      authMethod: auth.authMethod ?? "wagmi",
      authProvider: auth.authMethod ?? "wagmi",
      authValue: auth.authValue,
      primaryLabel: formatWalletAddress(address) ?? "Connected wallet",
      secondaryLabel:
        walletName ??
        formatAuthMethod(auth.authMethod ?? "wagmi") ??
        formatWalletProvider(auth.provider),
      ...baseSvm,
    };
  }

  if (svmAddress) {
    return {
      status: "connected",
      isConnected: true,
      walletKind: undefined,
      aaMode: undefined,
      chainId,
      svmAddress,
      sessionProvider: auth.sessionProvider,
      walletSource: "injected",
      walletProvider: auth.legacyWalletProvider,
      walletProviderSubject: auth.subject,
      authMethod: auth.authMethod,
      authProvider: auth.authMethod,
      authValue: auth.authValue,
      primaryLabel: formatWalletAddress(svmAddress) ?? "Connected Solana wallet",
      secondaryLabel: "Solana",
      svmCluster: svmIdentity?.cluster,
      svmWalletName: svmIdentity?.walletName,
      svmTransport,
      svmCapabilities,
      solanaCluster: svmIdentity?.cluster,
      solanaWalletName: svmIdentity?.walletName,
      solanaTransport: svmTransport,
      solanaCapabilities: svmCapabilities,
    };
  }

  return {
    ...AOMI_SESSION_DISCONNECTED_IDENTITY,
    chainId,
    sessionProvider: auth.sessionProvider,
    walletProvider: auth.legacyWalletProvider,
    walletProviderSubject: auth.subject,
    authMethod: auth.authMethod,
    authProvider: auth.authMethod,
    authValue: auth.authValue,
    svmCluster: svmIdentity?.cluster,
    solanaCluster: svmIdentity?.cluster,
  };
}

"use client";

import type { AomiAccount, AomiWalletKit } from "../types";
import type { WalletRegistryStore } from "../registry/store";
import type { AuthRuntime, ExecutionRuntime } from "./types";
import type { EvmWalletRuntime } from "../runtime/evm/wallet-runtime";
import type { SvmWalletRuntime, SvmIdentity } from "./types";
import { toRegistryFamily } from "../wallet-utils";

type BuildWalletKitActionsParams = {
  accounts: readonly AomiAccount[];
  auth: AuthRuntime;
  evm: EvmWalletRuntime;
  svm?: SvmWalletRuntime;
  execution: ExecutionRuntime;
  registryStore: WalletRegistryStore;
  evmAddress?: string;
  registryEvmConnected: boolean;
  svmIdentity?: SvmIdentity;
};

type WalletKitActions = Pick<
  AomiWalletKit,
  | "selectAccount"
  | "connectEvmWallet"
  | "connectSocial"
  | "connectSolanaWallet"
  | "connect"
  | "disconnect"
  | "openAccountUI"
  | "switchChain"
  | "selectNetwork"
>;

export function buildWalletKitActions({
  accounts,
  auth,
  evm,
  svm,
  execution,
  registryStore,
  evmAddress,
  registryEvmConnected,
  svmIdentity,
}: BuildWalletKitActionsParams): WalletKitActions {
  return {
    selectAccount: async (id: string) => {
      const target = accounts.find(
        (account) =>
          account.id === id ||
          (account.family === "evm" && account.connectorIds?.includes(id)),
      );
      if (!target) {
        throw new Error(`Unknown account: ${id}`);
      }
      if (target.family === "evm") {
        await evm.selectAccount(id);
        return;
      }
      await svm?.selectAccount(id);
    },
    connectEvmWallet: evm.connect,
    connectSocial: async (id: string) => {
      await auth.login?.(`social-login:${id}`);
    },
    connectSolanaWallet: svm
      ? async (walletName: string) => {
          await svm.connect(walletName);
        }
      : undefined,
    connect: async (options) => {
      const requestedFamily = toRegistryFamily(options?.family);
      if (requestedFamily === "svm" && svm) {
        await svm.connect();
        return;
      }
      if (requestedFamily === "evm" && (evmAddress || registryEvmConnected)) {
        return;
      }
      await auth.login?.("auth-modal");
    },
    disconnect: async (options) => {
      if (options?.accountId) {
        const target = accounts.find((a) => a.id === options.accountId);
        if (target?.family === "evm") {
          await evm.disconnect(target.id);
        }
        if (target?.family === "svm") {
          await svm?.disconnect(target.id);
        }
        if (target && options.providerSignOut) {
          auth.startFlow?.("provider-logout");
          await auth.logout?.();
        }
        return;
      }

      const requestedFamily = options?.family ?? "all";
      const registryFamily =
        requestedFamily === "all" ? "all" : toRegistryFamily(requestedFamily);
      const wantsAll = requestedFamily === "all";
      auth.startFlow?.(wantsAll ? "provider-logout" : "family-disconnect");
      if (wantsAll) {
        registryStore.dispatch({
          type: "user/disconnect-family",
          family: "all",
          now: Date.now(),
        });
        await auth.logout?.();
        return;
      }
      if (registryFamily === "evm") {
        await evm.disconnect();
        return;
      }
      await svm?.disconnect();
    },
    openAccountUI: async (options) => {
      const requestedFamily = toRegistryFamily(options?.family);
      if (requestedFamily === "svm" && svm && !svmIdentity?.address) {
        await svm.connect();
        return;
      }
      await auth.openAccountUI?.("account-modal", "ACCOUNT_MAIN");
    },
    switchChain: execution.evm.switchChainAsync
      ? async (chainId: number) => evm.selectNetwork(chainId)
      : undefined,
    selectNetwork: async (target) => {
      if (target.family === "evm") {
        await evm.selectNetwork(target.chainId);
        return;
      }
      await svm?.selectNetwork(target.networkId);
    },
  } satisfies WalletKitActions;
}

"use client";

import type { AomiAccount, AomiWalletOption } from "../types";
import type { AccountWallet } from "../account/types";
import type { AuthRuntime } from "./types";
import { toRegistryFamily, walletKey } from "../wallet-utils";

export type WalletRowAction =
  | { kind: "select"; label: string }
  | { kind: "connect"; label: string }
  | { kind: "authenticate"; label: string }
  | { kind: "disconnect"; label: string }
  | { kind: "signout"; label: string }
  | { kind: "manage"; label: string }
  | { kind: "link"; label: string }
  | { kind: "unlink"; label: string };

export type WalletModalRow = {
  id: string;
  family: AomiAccount["family"];
  address?: string;
  chainId?: number;
  label: string;
  walletName?: string;
  iconUrl?: string;
  kind?: AomiWalletOption["kind"] | "social";
  source: "live" | "embedded" | "stored" | "option";
  status: "active" | "connected" | "stored" | "available" | "unavailable";
  provider?: string;
  walletKind?: AccountWallet["kind"];
  linked?: boolean;
  linkedVia?: AomiAccount["linkedVia"];
  capability?: "read" | "write";
  manageable?: boolean;
  actions: WalletRowAction[];
};

export function mergeWalletRows({
  accounts,
  storedWallets = [],
  canLinkWallet = false,
  auth,
  options = [],
}: {
  accounts: readonly AomiAccount[];
  storedWallets?: readonly AccountWallet[];
  canLinkWallet?: boolean;
  auth?: Pick<AuthRuntime, "provider" | "status">;
  options?: readonly AomiWalletOption[];
}): WalletModalRow[] {
  const rows: WalletModalRow[] = accounts.map((account) => {
    const stored = storedWallets.find(
      (wallet) =>
        wallet.family === account.family &&
        walletKey(wallet.family, wallet.address) ===
          walletKey(account.family, account.address),
    );
    const linked = account.linked ?? Boolean(stored);
    const actions: WalletRowAction[] = account.actions?.length
      ? account.actions.map((action) => ({
          kind: action.kind,
          label:
            action.label ??
            (action.kind === "manage"
              ? "Manage"
              : action.kind === "signout"
                ? "Sign out"
                : "Disconnect"),
        }))
      : defaultLiveWalletActions({ account, linked, canLinkWallet });
    return {
      id: account.id,
      family: account.family,
      address: account.address,
      chainId: account.chainId,
      label: account.label ?? account.walletName ?? account.address,
      walletName: account.walletName,
      source: "live" as const,
      status: account.active ? ("active" as const) : ("connected" as const),
      provider: account.provider ?? stored?.provider,
      walletKind: account.walletKind ?? stored?.kind,
      linked,
      linkedVia: account.linkedVia ?? stored?.linkedVia,
      capability: account.capability ?? stored?.capability,
      manageable: account.manageable,
      actions,
    };
  });

  const liveKeys = new Set(
    accounts.map((account) => walletKey(account.family, account.address)),
  );
  for (const wallet of storedWallets) {
    if (liveKeys.has(walletKey(wallet.family, wallet.address))) continue;
    const embeddedSignedOut =
      wallet.kind === "embedded" &&
      wallet.provider === auth?.provider &&
      auth?.status !== "authenticated";
    rows.push({
      id: wallet.id,
      family: wallet.family,
      address: wallet.address,
      label: wallet.label ?? wallet.address,
      source: "stored",
      status: "stored",
      provider: wallet.provider,
      walletKind: wallet.kind,
      linked: true,
      capability: wallet.capability,
      actions: [
        embeddedSignedOut
          ? { kind: "authenticate", label: "Sign in" }
          : { kind: "connect", label: "Connect" },
      ],
    });
  }

  for (const option of options) {
    rows.push({
      id: option.id,
      family:
        option.family === "multichain"
          ? "evm"
          : toRegistryFamily(option.family),
      label: option.label,
      walletName: option.label,
      iconUrl: option.iconUrl,
      kind: option.kind,
      source: "option",
      status: option.status === "unavailable" ? "unavailable" : "available",
      provider: option.connectorId,
      actions: [
        {
          kind: option.kind === "social" ? "authenticate" : "connect",
          label: option.kind === "social" ? "Sign in" : "Connect",
        },
      ],
    });
  }

  return rows;
}

function defaultLiveWalletActions({
  account,
  linked,
  canLinkWallet,
}: {
  account: AomiAccount;
  linked: boolean;
  canLinkWallet: boolean;
}): WalletRowAction[] {
  const actions: WalletRowAction[] = [];
  if (canLinkWallet && !linked && account.family === "evm") {
    actions.push({ kind: "link", label: "Link" });
  }
  actions.push(
    account.manageable
      ? { kind: "manage", label: "Manage" }
      : { kind: "disconnect", label: "Disconnect" },
  );
  return actions;
}

